    23	
    24	    public String request(String orderNo, List<Integer> lineNos, LocalDate day) {
    25	        Order order = orders.find(orderNo).orElseThrow(() -> new IllegalArgumentException("no order " + orderNo));
    26	        if (lineNos.isEmpty()) throw new IllegalArgumentException("no lines to refund");
    27	        Set<Integer> wanted = new LinkedHashSet<>(lineNos);
    28	        if (wanted.size() != lineNos.size()) throw new IllegalArgumentException("line listed twice");
    29	        Set<Integer> taken = new LinkedHashSet<>();
    30	        for (RefundLine r : refunds.byOrder(orderNo)) taken.add(r.lineNo());
    31	        for (int n : wanted) {
    32	            order.line(n);
    33	            if (taken.contains(n)) throw new IllegalStateException("line " + n + " of " + orderNo + " already refunded");
    34	        }
    35	        String id = refunds.nextRequestId();
    36	        for (int n : wanted) {
    37	            OrderLine line = order.line(n);
    38	            refunds.add(new RefundLine(id, orderNo, n, order.tid(), line.paid(), day));
    39	        }
    40	        return id;
    41	    }
